INSERT INTO AD_CtxHelpMsg (AD_CtxHelpMsg_ID, AD_CtxHelpMsg_UU, AD_CtxHelp_ID, AD_Client_ID, AD_Org_ID, Created, CreatedBy, Updated, UpdatedBy, IsActive, MsgText)
SELECT COALESCE((SELECT AD_CtxHelpMsg_ID FROM AD_CtxHelpMsg WHERE AD_CtxHelpMsg_UU='498dcddc-a565-5776-bee2-9ad650a68660'), nextidfunc((SELECT AD_Sequence_ID FROM AD_Sequence WHERE Name='AD_CtxHelpMsg' AND IsTableID='Y')::integer, 'N')), '498dcddc-a565-5776-bee2-9ad650a68660', toRecordId('AD_CtxHelp', '2296041b-0c8b-550a-abab-7b73e9c6df3b'), 0, 0, now(), 100, now(), 100, 'Y', (SELECT x.dict || COALESCE(string_agg(b.html, '' ORDER BY b.k) FILTER (WHERE b.k <= x.j), '') || COALESCE(max(b.more) FILTER (WHERE b.k = x.j + 1), '') FROM (SELECT y.dict, y.l, COALESCE((SELECT min(c.k) FROM (SELECT k, sum(length(html)) OVER (ORDER BY k) AS cum, nextlen FROM blk WHERE lang = y.l) c WHERE length(y.dict) + c.cum + c.nextlen > y.lim) - 1, (SELECT max(k) FROM blk WHERE lang = y.l)) AS j FROM (SELECT '<p><strong>' || r.Name || '</strong></p>' || COALESCE('<p><em>' || NULLIF(r.Description, '') || '</em></p>', '') || COALESCE('<p>' || NULLIF(r.Help, '') || '</p>', '') || '<hr>' AS dict, 'en' AS l, (SELECT c.FieldLength FROM AD_Column c JOIN AD_Table tb ON tb.AD_Table_ID=c.AD_Table_ID WHERE tb.TableName='AD_CtxHelpMsg' AND c.ColumnName='MsgText') AS lim) y) x JOIN blk b ON b.lang = x.l GROUP BY x.dict, x.j)
FROM AD_Tab r WHERE r.AD_Tab_ID=186
ON CONFLICT (AD_CtxHelpMsg_UU) DO UPDATE SET MsgText=EXCLUDED.MsgText, Updated=now() WHERE AD_CtxHelpMsg.MsgText IS DISTINCT FROM EXCLUDED.MsgText;
