  ('zh_CN', 5, '<p><b>Do it.</b> Fill <b>Order</b>, then <b>Order Line</b>, <b>Order Tax</b>, <b>Payment Schedule</b>, <b>POS Payment</b>; then the Document Action <b>Complete</b>.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/LegacyOracleAdapterSpec/" target="_blank">Sales Order …</a></p>', 113),
