INSERT INTO AD_CtxHelpMsg_Trl (AD_CtxHelpMsg_ID, AD_Language, AD_CtxHelpMsg_Trl_UU, AD_Client_ID, AD_Org_ID, Created, CreatedBy, Updated, UpdatedBy, IsActive, IsTranslated, MsgText)
SELECT toRecordId('AD_CtxHelpMsg', '498dcddc-a565-5776-bee2-9ad650a68660'), r.AD_Language, generate_uuid(), 0, 0, now(), 100, now(), 100, 'Y', 'N', (SELECT x.dict || COALESCE(string_agg(b.html, '' ORDER BY b.k) FILTER (WHERE b.k <= x.j), '') || COALESCE(max(b.more) FILTER (WHERE b.k = x.j + 1), '') FROM (SELECT y.dict, y.l, COALESCE((SELECT min(c.k) FROM (SELECT k, sum(length(html)) OVER (ORDER BY k) AS cum, nextlen FROM blk WHERE lang = y.l) c WHERE length(y.dict) + c.cum + c.nextlen > y.lim) - 1, (SELECT max(k) FROM blk WHERE lang = y.l)) AS j FROM (SELECT '<p><strong>' || r.Name || '</strong></p>' || COALESCE('<p><em>' || NULLIF(r.Description, '') || '</em></p>', '') || COALESCE('<p>' || NULLIF(r.Help, '') || '</p>', '') || '<hr>' AS dict, CASE WHEN EXISTS (SELECT 1 FROM blk WHERE lang = r.AD_Language) THEN r.AD_Language ELSE 'en' END AS l, (SELECT c.FieldLength FROM AD_Column c JOIN AD_Table tb ON tb.AD_Table_ID=c.AD_Table_ID WHERE tb.TableName='AD_CtxHelpMsg_Trl' AND c.ColumnName='MsgText') AS lim) y) x JOIN blk b ON b.lang = x.l GROUP BY x.dict, x.j)
FROM AD_Tab_Trl r WHERE r.AD_Tab_ID=186
ON CONFLICT (AD_CtxHelpMsg_ID, AD_Language) DO UPDATE SET MsgText=EXCLUDED.MsgText, Updated=now() WHERE AD_CtxHelpMsg_Trl.MsgText IS DISTINCT FROM EXCLUDED.MsgText;
UPDATE AD_Tab SET AD_CtxHelp_ID=toRecordId('AD_CtxHelp', '2296041b-0c8b-550a-abab-7b73e9c6df3b'), Updated=now() WHERE AD_Tab_ID=186 AND AD_CtxHelp_ID IS NULL;

-- tab 257 Shipment: UG2 (twin help 1000001)
INSERT INTO AD_CtxHelp (AD_CtxHelp_ID, AD_CtxHelp_UU, AD_Client_ID, AD_Org_ID, Created, CreatedBy, Updated, UpdatedBy, IsActive, CtxType, Name, Description)
SELECT COALESCE((SELECT AD_CtxHelp_ID FROM AD_CtxHelp WHERE AD_CtxHelp_UU='88553452-b4a3-594f-936c-51f8d4303780'), nextidfunc((SELECT AD_Sequence_ID FROM AD_Sequence WHERE Name='AD_CtxHelp' AND IsTableID='Y')::integer, 'N')), '88553452-b4a3-594f-936c-51f8d4303780', 0, 0, now(), 100, now(), 100, 'Y', 'T', '2 · Shipment', 'https://red1oon.github.io/BIMCompiler/ERPUserGuide/#2-shipment'
ON CONFLICT (AD_CtxHelp_UU) DO UPDATE SET Name=EXCLUDED.Name, Description=EXCLUDED.Description, Updated=now() WHERE (AD_CtxHelp.Name, AD_CtxHelp.Description) IS DISTINCT FROM (EXCLUDED.Name, EXCLUDED.Description);
WITH blk(lang, k, html, more, nextlen) AS (VALUES
  ('en', 1, '<p><strong>2 · Shipment</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#2-shipment" target="_blank">2 · Shipment …</a></p>', 114),
  ('en', 2, '<p>The <b>Shipment</b> (<code><b>M_InOut</b></code>) that Complete generated is a real window of its own (⌂ → Inventory → Shipment) — open it to see the same document from the warehouse side. On-hand for every shipped product drops immediately; the shipment also carries its own GL leg (Cost of Goods Sold against Inventory), not just a paper movement.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#2-shipment" target="_blank">2 · Shipment …</a></p>', 0),
  ('de_DE', 1, '<p><strong>2 · Lieferung</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#2-shipment" target="_blank">2 · Lieferung …</a></p>', 115),
  ('de_DE', 2, '<p>Die <b><b>Lieferung (Kunde)</b></b> (<code>M_InOut</code>), die Fertigstellen erzeugt hat, ist ein eigenes Fenster (⌂ → Lager → Lieferung) — öffnen Sie es, um denselben Beleg von der Lagerseite zu sehen. Der Bestand jedes gelieferten Produkts sinkt sofort; die Lieferung hat außerdem eine eigene Buchung (Wareneinsatz gegen Lagerbestand), nicht nur eine Papierbewegung.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#2-shipment" target="_blank">2 · Lieferung …</a></p>', 0),
  ('zh_CN', 1, '<p><strong>2 · 出货</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#2-shipment" target="_blank">2 · 出货 …</a></p>', 108),
  ('zh_CN', 2, '<p>完成时生成的<b><b>物料出货(客户/公司)</b></b>（<code>M_InOut</code>）是一个独立的窗口（⌂ → 库存 → 出货）——打开它，从仓库一侧看同一张单据。每个已出货产品的现有库存立即减少；出货单还带有自己的总账分录（销货成本对库存），而不只是纸面上的移动。</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#2-shipment" target="_blank">2 · 出货 …</a></p>', 0))
INSERT INTO AD_CtxHelpMsg (AD_CtxHelpMsg_ID, AD_CtxHelpMsg_UU, AD_CtxHelp_ID, AD_Client_ID, AD_Org_ID, Created, CreatedBy, Updated, UpdatedBy, IsActive, MsgText)
SELECT COALESCE((SELECT AD_CtxHelpMsg_ID FROM AD_CtxHelpMsg WHERE AD_CtxHelpMsg_UU='d2297abb-346f-57dd-ace4-141a5691feca'), nextidfunc((SELECT AD_Sequence_ID FROM AD_Sequence WHERE Name='AD_CtxHelpMsg' AND IsTableID='Y')::integer, 'N')), 'd2297abb-346f-57dd-ace4-141a5691feca', toRecordId('AD_CtxHelp', '88553452-b4a3-594f-936c-51f8d4303780'), 0, 0, now(), 100, now(), 100, 'Y', (SELECT x.dict || COALESCE(string_agg(b.html, '' ORDER BY b.k) FILTER (WHERE b.k <= x.j), '') || COALESCE(max(b.more) FILTER (WHERE b.k = x.j + 1), '') FROM (SELECT y.dict, y.l, COALESCE((SELECT min(c.k) FROM (SELECT k, sum(length(html)) OVER (ORDER BY k) AS cum, nextlen FROM blk WHERE lang = y.l) c WHERE length(y.dict) + c.cum + c.nextlen > y.lim) - 1, (SELECT max(k) FROM blk WHERE lang = y.l)) AS j FROM (SELECT '<p><strong>' || r.Name || '</strong></p>' || COALESCE('<p><em>' || NULLIF(r.Description, '') || '</em></p>', '') || COALESCE('<p>' || NULLIF(r.Help, '') || '</p>', '') || '<hr>' AS dict, 'en' AS l, (SELECT c.FieldLength FROM AD_Column c JOIN AD_Table tb ON tb.AD_Table_ID=c.AD_Table_ID WHERE tb.TableName='AD_CtxHelpMsg' AND c.ColumnName='MsgText') AS lim) y) x JOIN blk b ON b.lang = x.l GROUP BY x.dict, x.j)
FROM AD_Tab r WHERE r.AD_Tab_ID=257
ON CONFLICT (AD_CtxHelpMsg_UU) DO UPDATE SET MsgText=EXCLUDED.MsgText, Updated=now() WHERE AD_CtxHelpMsg.MsgText IS DISTINCT FROM EXCLUDED.MsgText;
WITH blk(lang, k, html, more, nextlen) AS (VALUES
  ('en', 1, '<p><strong>2 · Shipment</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#2-shipment" target="_blank">2 · Shipment …</a></p>', 114),
  ('en', 2, '<p>The <b>Shipment</b> (<code><b>M_InOut</b></code>) that Complete generated is a real window of its own (⌂ → Inventory → Shipment) — open it to see the same document from the warehouse side. On-hand for every shipped product drops immediately; the shipment also carries its own GL leg (Cost of Goods Sold against Inventory), not just a paper movement.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#2-shipment" target="_blank">2 · Shipment …</a></p>', 0),
  ('de_DE', 1, '<p><strong>2 · Lieferung</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#2-shipment" target="_blank">2 · Lieferung …</a></p>', 115),
  ('de_DE', 2, '<p>Die <b><b>Lieferung (Kunde)</b></b> (<code>M_InOut</code>), die Fertigstellen erzeugt hat, ist ein eigenes Fenster (⌂ → Lager → Lieferung) — öffnen Sie es, um denselben Beleg von der Lagerseite zu sehen. Der Bestand jedes gelieferten Produkts sinkt sofort; die Lieferung hat außerdem eine eigene Buchung (Wareneinsatz gegen Lagerbestand), nicht nur eine Papierbewegung.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#2-shipment" target="_blank">2 · Lieferung …</a></p>', 0),
  ('zh_CN', 1, '<p><strong>2 · 出货</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#2-shipment" target="_blank">2 · 出货 …</a></p>', 108),
  ('zh_CN', 2, '<p>完成时生成的<b><b>物料出货(客户/公司)</b></b>（<code>M_InOut</code>）是一个独立的窗口（⌂ → 库存 → 出货）——打开它，从仓库一侧看同一张单据。每个已出货产品的现有库存立即减少；出货单还带有自己的总账分录（销货成本对库存），而不只是纸面上的移动。</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#2-shipment" target="_blank">2 · 出货 …</a></p>', 0))
INSERT INTO AD_CtxHelpMsg_Trl (AD_CtxHelpMsg_ID, AD_Language, AD_CtxHelpMsg_Trl_UU, AD_Client_ID, AD_Org_ID, Created, CreatedBy, Updated, UpdatedBy, IsActive, IsTranslated, MsgText)
SELECT toRecordId('AD_CtxHelpMsg', 'd2297abb-346f-57dd-ace4-141a5691feca'), r.AD_Language, generate_uuid(), 0, 0, now(), 100, now(), 100, 'Y', 'N', (SELECT x.dict || COALESCE(string_agg(b.html, '' ORDER BY b.k) FILTER (WHERE b.k <= x.j), '') || COALESCE(max(b.more) FILTER (WHERE b.k = x.j + 1), '') FROM (SELECT y.dict, y.l, COALESCE((SELECT min(c.k) FROM (SELECT k, sum(length(html)) OVER (ORDER BY k) AS cum, nextlen FROM blk WHERE lang = y.l) c WHERE length(y.dict) + c.cum + c.nextlen > y.lim) - 1, (SELECT max(k) FROM blk WHERE lang = y.l)) AS j FROM (SELECT '<p><strong>' || r.Name || '</strong></p>' || COALESCE('<p><em>' || NULLIF(r.Description, '') || '</em></p>', '') || COALESCE('<p>' || NULLIF(r.Help, '') || '</p>', '') || '<hr>' AS dict, CASE WHEN EXISTS (SELECT 1 FROM blk WHERE lang = r.AD_Language) THEN r.AD_Language ELSE 'en' END AS l, (SELECT c.FieldLength FROM AD_Column c JOIN AD_Table tb ON tb.AD_Table_ID=c.AD_Table_ID WHERE tb.TableName='AD_CtxHelpMsg_Trl' AND c.ColumnName='MsgText') AS lim) y) x JOIN blk b ON b.lang = x.l GROUP BY x.dict, x.j)
