-- tab 263 Invoice: UG3 (twin help 1000002)
INSERT INTO AD_CtxHelp (AD_CtxHelp_ID, AD_CtxHelp_UU, AD_Client_ID, AD_Org_ID, Created, CreatedBy, Updated, UpdatedBy, IsActive, CtxType, Name, Description)
SELECT COALESCE((SELECT AD_CtxHelp_ID FROM AD_CtxHelp WHERE AD_CtxHelp_UU='5839dce2-b7ee-59e4-beed-f7c1271e6fb2'), nextidfunc((SELECT AD_Sequence_ID FROM AD_Sequence WHERE Name='AD_CtxHelp' AND IsTableID='Y')::integer, 'N')), '5839dce2-b7ee-59e4-beed-f7c1271e6fb2', 0, 0, now(), 100, now(), 100, 'Y', 'T', '3 · Customer Invoice → AR', 'https://red1oon.github.io/BIMCompiler/ERPUserGuide/#3-customer-invoice-ar'
ON CONFLICT (AD_CtxHelp_UU) DO UPDATE SET Name=EXCLUDED.Name, Description=EXCLUDED.Description, Updated=now() WHERE (AD_CtxHelp.Name, AD_CtxHelp.Description) IS DISTINCT FROM (EXCLUDED.Name, EXCLUDED.Description);
WITH blk(lang, k, html, more, nextlen) AS (VALUES
  ('en', 1, '<p><strong>3 · Customer Invoice → AR</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#3-customer-invoice-ar" target="_blank">3 · Customer Invoice → AR …</a></p>', 138),
  ('en', 2, '<p>The <b><b>Invoice</b></b> the same Complete generated posts DR <b>Receivable</b> / CR <b>Revenue</b> (per line) / CR <b>Tax Due</b>. Open <b>Posting Preview</b> on the invoice (any completed document has this) to see that exact journal before you take our word for it — it is the SAME derivation the guide''s Posting-Preview panel runs live, not a separate report-only calculation.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#3-customer-invoice-ar" target="_blank">3 · Customer Invoice → AR …</a></p>', 0),
  ('de_DE', 1, '<p><strong>3 · Kundenrechnung → Forderungen</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#3-customer-invoice-ar" target="_blank">3 · Kundenrechnung → Forderungen …</a></p>', 145),
  ('de_DE', 2, '<p>Die <b><b>Rechnung (Kunde)</b></b>, die dasselbe Fertigstellen erzeugt hat, bucht Soll <b>Forderungen</b> / Haben <b>Erlöse</b> (je Position) / Haben <b>Umsatzsteuer</b>. Öffnen Sie die <b>Buchungsvorschau</b> der Rechnung (jeder fertiggestellte Beleg hat sie), um genau diese Buchung zu sehen, bevor Sie uns glauben — es ist DIESELBE Herleitung, die die Buchungsvorschau des Leitfadens live ausführt, keine separate Berichtsberechnung.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#3-customer-invoice-ar" target="_blank">3 · Kundenrechnung → Forderungen …</a></p>', 0),
  ('zh_CN', 1, '<p><strong>3 · 客户发票 → 应收</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#3-customer-invoice-ar" target="_blank">3 · 客户发票 → 应收 …</a></p>', 126),
  ('zh_CN', 2, '<p>同一次完成生成的<b><b>发票(客户/公司)</b></b>记账：借<b>应收账款</b> / 贷<b>收入</b>（按行）/ 贷<b>应交税金</b>。在发票上打开<b>记账预览</b>（任何已完成的单据都有）——先看这张分录，再相信我们的说法；它和指南里的记账预览面板实时运行的是同一个推导，不是单独的报表计算。</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#3-customer-invoice-ar" target="_blank">3 · 客户发票 → 应收 …</a></p>', 0))
