  ('en', 1, '<p><strong>6 · Purchase Order → Receipt → Vendor Invoice → Match</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#6-purchase-order-receipt-vendor-invoice-match" target="_blank">6 · Purchase Order → Receipt → Vendor Invoice → Match …</a></p>', 190),
  ('en', 2, '<p>Accepting a replenishment proposal (or creating one by hand, ⌂ → Purchasing → <b>Purchase Order</b>) and completing it is the buy-side mirror of step 1. It flows the same way in reverse:</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#6-purchase-order-receipt-vendor-invoice-match" target="_blank">6 · Purchase Order → Receipt → Vendor Invoice → Match …</a></p>', 190),
  ('en', 3, '<ul><li><b><b>Purchase Order</b></b> — completes; under this seed''s configuration (commitment accounting off) it posts no commitment/reservation entry — an honest, config-derived ∅, not a gap.</li><li><b>Receipt</b> (<code><b>M_InOut</b></code>, incoming) — stock arrives, on-hand rises.</li><li><b>Vendor Invoice</b> — posts DR <b>Inventory Clearing</b> / CR <b>Vendor Liability</b>.</li><li><b>Match</b> (<code><b>M_MatchInv</b></code>) — clears the Inventory-Clearing/Not-Invoiced-Receipts pair the receipt and invoice each opened, including any invoice-price-variance split against on-hand at match time. <code><b>M_MatchPO</b></code>''s own leg stays an honest ∅ under this seed''s Average costing (the variance-posting branch only fires under Standard costing) — a config fact, proven by flipping it in the witness, not assumed.</li></ul>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#6-purchase-order-receipt-vendor-invoice-match" target="_blank">6 · Purchase Order → Receipt → Vendor Invoice → Match …</a></p>', 0),
  ('de_DE', 1, '<p><strong>6 · Bestellung → Wareneingang → Lieferantenrechnung → Zuordnung</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#6-purchase-order-receipt-vendor-invoice-match" target="_blank">6 · Bestellung → Wareneingang → Lieferantenrechnung → Zuordnung …</a></p>', 200),
  ('de_DE', 2, '<p>Einen Nachbestellungsvorschlag annehmen (oder eine Bestellung von Hand anlegen, ⌂ → Einkauf → <b><b>Bestellung</b></b>) und fertigstellen ist das Spiegelbild von Schritt 1 auf der Einkaufsseite. Es läuft genauso, nur umgekehrt:</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#6-purchase-order-receipt-vendor-invoice-match" target="_blank">6 · Bestellung → Wareneingang → Lieferantenrechnung → Zuordnung …</a></p>', 200),
  ('de_DE', 3, '<ul><li><b><b>Bestellung</b></b> — wird fertiggestellt; mit der Konfiguration dieser Daten (Obligo-Buchhaltung aus) bucht sie keinen Obligo- oder Reservierungseintrag — ein ehrliches, aus der Konfiguration folgendes ∅, keine Lücke.</li><li><b><b>Wareneingang</b></b> (<code>M_InOut</code>, eingehend) — die Ware kommt an, der Bestand steigt.</li><li><b><b>Rechnung (Lieferant)</b></b> — bucht Soll <b>Verrechnung Wareneingang</b> / Haben <b>Verbindlichkeiten</b>.</li><li><b>Zuordnung</b> (<code>M_MatchInv</code>) — gleicht das Paar Verrechnung Wareneingang / nicht fakturierte Eingänge aus, das Eingang und Rechnung jeweils eröffnet haben, einschließlich einer Preisabweichung der Rechnung, aufgeteilt gegen den Bestand zum Zeitpunkt der Zuordnung. Die eigene Buchung von <code>M_MatchPO</code> bleibt mit der Durchschnittskostenrechnung dieser Daten ein ehrliches ∅ (der Zweig für Abweichungsbuchungen greift nur bei Standardkosten) — eine Tatsache der Konfiguration, im Witness durch Umschalten bewiesen, nicht angenommen.</li></ul>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#6-purchase-order-receipt-vendor-invoice-match" target="_blank">6 · Bestellung → Wareneingang → Lieferantenrechnung → Zuordnung …</a></p>', 0))
INSERT INTO AD_CtxHelpMsg_Trl (AD_CtxHelpMsg_ID, AD_Language, AD_CtxHelpMsg_Trl_UU, AD_Client_ID, AD_Org_ID, Created, CreatedBy, Updated, UpdatedBy, IsActive, IsTranslated, MsgText)
SELECT toRecordId('AD_CtxHelpMsg', '6512ec99-5f00-5ea8-93bb-6e939d247bf8'), r.AD_Language, generate_uuid(), 0, 0, now(), 100, now(), 100, 'Y', 'N', (SELECT x.dict || COALESCE(string_agg(b.html, '' ORDER BY b.k) FILTER (WHERE b.k <= x.j), '') || COALESCE(max(b.more) FILTER (WHERE b.k = x.j + 1), '') FROM (SELECT y.dict, y.l, COALESCE((SELECT min(c.k) FROM (SELECT k, sum(length(html)) OVER (ORDER BY k) AS cum, nextlen FROM blk WHERE lang = y.l) c WHERE length(y.dict) + c.cum + c.nextlen > y.lim) - 1, (SELECT max(k) FROM blk WHERE lang = y.l)) AS j FROM (SELECT '<p><strong>' || r.Name || '</strong></p>' || COALESCE('<p><em>' || NULLIF(r.Description, '') || '</em></p>', '') || COALESCE('<p>' || NULLIF(r.Help, '') || '</p>', '') || '<hr>' AS dict, CASE WHEN EXISTS (SELECT 1 FROM blk WHERE lang = r.AD_Language) THEN r.AD_Language ELSE 'en' END AS l, (SELECT c.FieldLength FROM AD_Column c JOIN AD_Table tb ON tb.AD_Table_ID=c.AD_Table_ID WHERE tb.TableName='AD_CtxHelpMsg_Trl' AND c.ColumnName='MsgText') AS lim) y) x JOIN blk b ON b.lang = x.l GROUP BY x.dict, x.j)
FROM AD_Tab_Trl r WHERE r.AD_Tab_ID=408
ON CONFLICT (AD_CtxHelpMsg_ID, AD_Language) DO UPDATE SET MsgText=EXCLUDED.MsgText, Updated=now() WHERE AD_CtxHelpMsg_Trl.MsgText IS DISTINCT FROM EXCLUDED.MsgText;
UPDATE AD_Tab SET AD_CtxHelp_ID=toRecordId('AD_CtxHelp', 'dd7d7d3e-3d73-5dfc-9743-754d4554a6ed'), Updated=now() WHERE AD_Tab_ID=408 AND AD_CtxHelp_ID IS NULL;

-- tab 200007 Journal: UG7 (twin help 1000006)
INSERT INTO AD_CtxHelp (AD_CtxHelp_ID, AD_CtxHelp_UU, AD_Client_ID, AD_Org_ID, Created, CreatedBy, Updated, UpdatedBy, IsActive, CtxType, Name, Description)
SELECT COALESCE((SELECT AD_CtxHelp_ID FROM AD_CtxHelp WHERE AD_CtxHelp_UU='7b1ff739-18bc-5fa8-81a5-0e46eb8222c2'), nextidfunc((SELECT AD_Sequence_ID FROM AD_Sequence WHERE Name='AD_CtxHelp' AND IsTableID='Y')::integer, 'N')), '7b1ff739-18bc-5fa8-81a5-0e46eb8222c2', 0, 0, now(), 100, now(), 100, 'Y', 'T', '7 · Final accounts (Journal)', 'https://red1oon.github.io/BIMCompiler/ERPUserGuide/#7-final-accounts'
ON CONFLICT (AD_CtxHelp_UU) DO UPDATE SET Name=EXCLUDED.Name, Description=EXCLUDED.Description, Updated=now() WHERE (AD_CtxHelp.Name, AD_CtxHelp.Description) IS DISTINCT FROM (EXCLUDED.Name, EXCLUDED.Description);
WITH blk(lang, k, html, more, nextlen) AS (VALUES
  ('en', 1, '<p><strong>7 · Final accounts</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#7-final-accounts" target="_blank">7 · Final accounts …</a></p>', 126),
  ('en', 2, '<p>Two more postings close the period: a <b><b>GL Journal</b></b> for anything that isn''t a document (a manual accrual, an inter-org transfer) and a <b><b>Bank Statement</b></b> reconciling the bank''s own records against what the ledger expects. Once every document for the period is posted, the period''s <code>fact_acct</code> <b>is</b> the ledger — there is no separate "close" step that recomputes anything; Trial Balance is a live fold of the same rows, and it balances to the cent.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#7-final-accounts" target="_blank">7 · Final accounts …</a></p>', 0),
  ('de_DE', 1, '<p><strong>7 · Abschluss</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#7-final-accounts" target="_blank">7 · Abschluss …</a></p>', 121),
  ('de_DE', 2, '<p>Zwei weitere Buchungen schließen die Periode: ein <b><b>Journal</b></b> für alles, was kein Beleg ist (eine manuelle Abgrenzung, eine Übertragung zwischen Organisationen), und ein <b><b>Bankauszug</b></b>, der die Aufzeichnungen der Bank mit dem abgleicht, was das Hauptbuch erwartet. Sobald jeder Beleg der Periode gebucht ist, <b>ist</b> <code>fact_acct</code> der Periode das Hauptbuch — es gibt keinen eigenen Abschlussschritt, der etwas neu berechnet; die Rohbilanz ist eine laufende Auswertung derselben Zeilen und geht auf den Cent auf.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#7-final-accounts" target="_blank">7 · Abschluss …</a></p>', 0))
