WITH blk(lang, k, html, more, nextlen) AS (VALUES
  ('en', 1, '<p><strong>8 · Financial reporting</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#8-financial-reporting" target="_blank">8 · Financial reporting …</a></p>', 136),
  ('en', 2, '<p>From here, everything is read-only fold: <b>Balance Sheet</b>, <b>Income Statement</b>, <b>Cash Flow</b>, and <b>Trial Balance</b> are all oracle-equivalent to the real ledger (§8 <i>Financial Reporting</i>, below, has the per-report cell counts), and the same ledger is what the <b>NinjaExcel</b> workbook lens (§8, "Excel Report") binds into your own spreadsheet layout.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#8-financial-reporting" target="_blank">8 · Financial reporting …</a></p>', 0),
  ('de_DE', 1, '<p><strong>8 · Finanzberichte</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#8-financial-reporting" target="_blank">8 · Finanzberichte …</a></p>', 131),
  ('de_DE', 2, '<p>Ab hier ist alles nur lesende Auswertung: <b>Bilanz</b>, <b>Gewinn- und Verlustrechnung</b>, <b>Kapitalflussrechnung</b> und <b>Rohbilanz</b> sind alle gleichwertig zum echten Hauptbuch (§8 <i>Finanzberichte</i> weiter unten nennt die Zellenzahlen je Bericht), und dasselbe Hauptbuch bindet die Arbeitsmappen-Ansicht <b>NinjaExcel</b> (§8, „Excel Report“) in Ihr eigenes Tabellenlayout ein. Der <b><b>Finanzbericht</b></b> ist das Fenster dazu.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#8-financial-reporting" target="_blank">8 · Finanzberichte …</a></p>', 0))
INSERT INTO AD_CtxHelpMsg (AD_CtxHelpMsg_ID, AD_CtxHelpMsg_UU, AD_CtxHelp_ID, AD_Client_ID, AD_Org_ID, Created, CreatedBy, Updated, UpdatedBy, IsActive, MsgText)
SELECT COALESCE((SELECT AD_CtxHelpMsg_ID FROM AD_CtxHelpMsg WHERE AD_CtxHelpMsg_UU='2c335202-1b9a-5e7f-824a-3c5ccd5ab7a9'), nextidfunc((SELECT AD_Sequence_ID FROM AD_Sequence WHERE Name='AD_CtxHelpMsg' AND IsTableID='Y')::integer, 'N')), '2c335202-1b9a-5e7f-824a-3c5ccd5ab7a9', toRecordId('AD_CtxHelp', '83765705-ba68-5d84-8dd7-17a23550b2d4'), 0, 0, now(), 100, now(), 100, 'Y', (SELECT x.dict || COALESCE(string_agg(b.html, '' ORDER BY b.k) FILTER (WHERE b.k <= x.j), '') || COALESCE(max(b.more) FILTER (WHERE b.k = x.j + 1), '') FROM (SELECT y.dict, y.l, COALESCE((SELECT min(c.k) FROM (SELECT k, sum(length(html)) OVER (ORDER BY k) AS cum, nextlen FROM blk WHERE lang = y.l) c WHERE length(y.dict) + c.cum + c.nextlen > y.lim) - 1, (SELECT max(k) FROM blk WHERE lang = y.l)) AS j FROM (SELECT '<p><strong>' || r.Name || '</strong></p>' || COALESCE('<p><em>' || NULLIF(r.Description, '') || '</em></p>', '') || COALESCE('<p>' || NULLIF(r.Help, '') || '</p>', '') || '<hr>' AS dict, 'en' AS l, (SELECT c.FieldLength FROM AD_Column c JOIN AD_Table tb ON tb.AD_Table_ID=c.AD_Table_ID WHERE tb.TableName='AD_CtxHelpMsg' AND c.ColumnName='MsgText') AS lim) y) x JOIN blk b ON b.lang = x.l GROUP BY x.dict, x.j)
FROM AD_Tab r WHERE r.AD_Tab_ID=372
ON CONFLICT (AD_CtxHelpMsg_UU) DO UPDATE SET MsgText=EXCLUDED.MsgText, Updated=now() WHERE AD_CtxHelpMsg.MsgText IS DISTINCT FROM EXCLUDED.MsgText;
WITH blk(lang, k, html, more, nextlen) AS (VALUES
