  ('en', 2, '<p>From here, everything is read-only fold: <b>Balance Sheet</b>, <b>Income Statement</b>, <b>Cash Flow</b>, and <b>Trial Balance</b> are all oracle-equivalent to the real ledger (§8 <i>Financial Reporting</i>, below, has the per-report cell counts), and the same ledger is what the <b>NinjaExcel</b> workbook lens (§8, "Excel Report") binds into your own spreadsheet layout.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#8-financial-reporting" target="_blank">8 · Financial reporting …</a></p>', 0),
  ('de_DE', 1, '<p><strong>8 · Finanzberichte</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#8-financial-reporting" target="_blank">8 · Finanzberichte …</a></p>', 131),
  ('de_DE', 2, '<p>Ab hier ist alles nur lesende Auswertung: <b>Bilanz</b>, <b>Gewinn- und Verlustrechnung</b>, <b>Kapitalflussrechnung</b> und <b>Rohbilanz</b> sind alle gleichwertig zum echten Hauptbuch (§8 <i>Finanzberichte</i> weiter unten nennt die Zellenzahlen je Bericht), und dasselbe Hauptbuch bindet die Arbeitsmappen-Ansicht <b>NinjaExcel</b> (§8, „Excel Report“) in Ihr eigenes Tabellenlayout ein. Der <b><b>Finanzbericht</b></b> ist das Fenster dazu.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#8-financial-reporting" target="_blank">8 · Finanzberichte …</a></p>', 0))
INSERT INTO AD_CtxHelpMsg_Trl (AD_CtxHelpMsg_ID, AD_Language, AD_CtxHelpMsg_Trl_UU, AD_Client_ID, AD_Org_ID, Created, CreatedBy, Updated, UpdatedBy, IsActive, IsTranslated, MsgText)
SELECT toRecordId('AD_CtxHelpMsg', '2c335202-1b9a-5e7f-824a-3c5ccd5ab7a9'), r.AD_Language, generate_uuid(), 0, 0, now(), 100, now(), 100, 'Y', 'N', (SELECT x.dict || COALESCE(string_agg(b.html, '' ORDER BY b.k) FILTER (WHERE b.k <= x.j), '') || COALESCE(max(b.more) FILTER (WHERE b.k = x.j + 1), '') FROM (SELECT y.dict, y.l, COALESCE((SELECT min(c.k) FROM (SELECT k, sum(length(html)) OVER (ORDER BY k) AS cum, nextlen FROM blk WHERE lang = y.l) c WHERE length(y.dict) + c.cum + c.nextlen > y.lim) - 1, (SELECT max(k) FROM blk WHERE lang = y.l)) AS j FROM (SELECT '<p><strong>' || r.Name || '</strong></p>' || COALESCE('<p><em>' || NULLIF(r.Description, '') || '</em></p>', '') || COALESCE('<p>' || NULLIF(r.Help, '') || '</p>', '') || '<hr>' AS dict, CASE WHEN EXISTS (SELECT 1 FROM blk WHERE lang = r.AD_Language) THEN r.AD_Language ELSE 'en' END AS l, (SELECT c.FieldLength FROM AD_Column c JOIN AD_Table tb ON tb.AD_Table_ID=c.AD_Table_ID WHERE tb.TableName='AD_CtxHelpMsg_Trl' AND c.ColumnName='MsgText') AS lim) y) x JOIN blk b ON b.lang = x.l GROUP BY x.dict, x.j)
FROM AD_Tab_Trl r WHERE r.AD_Tab_ID=372
ON CONFLICT (AD_CtxHelpMsg_ID, AD_Language) DO UPDATE SET MsgText=EXCLUDED.MsgText, Updated=now() WHERE AD_CtxHelpMsg_Trl.MsgText IS DISTINCT FROM EXCLUDED.MsgText;
UPDATE AD_Tab SET AD_CtxHelp_ID=toRecordId('AD_CtxHelp', '83765705-ba68-5d84-8dd7-17a23550b2d4'), Updated=now() WHERE AD_Tab_ID=372 AND AD_CtxHelp_ID IS NULL;

-- tab 294 Purchase Order: UG6 + FSD (twin help 1000008)
INSERT INTO AD_CtxHelp (AD_CtxHelp_ID, AD_CtxHelp_UU, AD_Client_ID, AD_Org_ID, Created, CreatedBy, Updated, UpdatedBy, IsActive, CtxType, Name, Description)
SELECT COALESCE((SELECT AD_CtxHelp_ID FROM AD_CtxHelp WHERE AD_CtxHelp_UU='58265c07-f5bc-52c2-9cc6-3527dace43ca'), nextidfunc((SELECT AD_Sequence_ID FROM AD_Sequence WHERE Name='AD_CtxHelp' AND IsTableID='Y')::integer, 'N')), '58265c07-f5bc-52c2-9cc6-3527dace43ca', 0, 0, now(), 100, now(), 100, 'Y', 'T', '6 · Purchase Order → Receipt → Vendor Invoice → Match + Part D — Your first purchase order (demo company)', 'https://red1oon.github.io/BIMCompiler/ERPUserGuide/#6-purchase-order-receipt-vendor-invoice-match'
ON CONFLICT (AD_CtxHelp_UU) DO UPDATE SET Name=EXCLUDED.Name, Description=EXCLUDED.Description, Updated=now() WHERE (AD_CtxHelp.Name, AD_CtxHelp.Description) IS DISTINCT FROM (EXCLUDED.Name, EXCLUDED.Description);
WITH blk(lang, k, html, more, nextlen) AS (VALUES
  ('en', 1, '<p><strong>6 · Purchase Order → Receipt → Vendor Invoice → Match</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#6-purchase-order-receipt-vendor-invoice-match" target="_blank">6 · Purchase Order → Receipt → Vendor Invoice → Match …</a></p>', 190),
  ('en', 2, '<p>Accepting a replenishment proposal (or creating one by hand, ⌂ → Purchasing → <b>Purchase Order</b>) and completing it is the buy-side mirror of step 1. It flows the same way in reverse:</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#6-purchase-order-receipt-vendor-invoice-match" target="_blank">6 · Purchase Order → Receipt → Vendor Invoice → Match …</a></p>', 190),
  ('en', 3, '<ul><li><b><b>Purchase Order</b></b> — completes; under this seed''s configuration (commitment accounting off) it posts no commitment/reservation entry — an honest, config-derived ∅, not a gap.</li><li><b>Receipt</b> (<code><b>M_InOut</b></code>, incoming) — stock arrives, on-hand rises.</li><li><b>Vendor Invoice</b> — posts DR <b>Inventory Clearing</b> / CR <b>Vendor Liability</b>.</li><li><b>Match</b> (<code><b>M_MatchInv</b></code>) — clears the Inventory-Clearing/Not-Invoiced-Receipts pair the receipt and invoice each opened, including any invoice-price-variance split against on-hand at match time. <code><b>M_MatchPO</b></code>''s own leg stays an honest ∅ under this seed''s Average costing (the variance-posting branch only fires under Standard costing) — a config fact, proven by flipping it in the witness, not assumed.</li></ul>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#6-purchase-order-receipt-vendor-invoice-match" target="_blank">6 · Purchase Order → Receipt → Vendor Invoice → Match …</a></p>', 188),
  ('en', 4, '<p><strong>Part D — Your first purchase order (demo company)</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERP_FirstSetup/#part-d-your-first-purchase-order-demo-company" target="_blank">Part D — Your first purchase order (demo company) …</a></p>', 188),
  ('en', 5, '<p>Same steps as Part C, in <b><b>Purchase Order</b></b> (window 181): vendor e.g. <i>Tree Farm Inc.</i>, document type <b>Purchase Order</b>, line tab <b>PO Line</b> (e.g. <i>Elm Tree</i> × 5 at 40.00), then <b>Complete</b>. Like a Standard Order, a standard Purchase Order creates no receipt or vendor invoice on Complete (verified: 0 new documents); the receipt is entered separately.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERP_FirstSetup/#part-d-your-first-purchase-order-demo-company" target="_blank">Part D — Your first purchase order (demo company) …</a></p>', 0),
  ('de_DE', 1, '<p><strong>6 · Bestellung → Wareneingang → Lieferantenrechnung → Zuordnung</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#6-purchase-order-receipt-vendor-invoice-match" target="_blank">6 · Bestellung → Wareneingang → Lieferantenrechnung → Zuordnung …</a></p>', 200),
  ('de_DE', 2, '<p>Einen Nachbestellungsvorschlag annehmen (oder eine Bestellung von Hand anlegen, ⌂ → Einkauf → <b><b>Bestellung</b></b>) und fertigstellen ist das Spiegelbild von Schritt 1 auf der Einkaufsseite. Es läuft genauso, nur umgekehrt:</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#6-purchase-order-receipt-vendor-invoice-match" target="_blank">6 · Bestellung → Wareneingang → Lieferantenrechnung → Zuordnung …</a></p>', 200),
  ('de_DE', 3, '<ul><li><b><b>Bestellung</b></b> — wird fertiggestellt; mit der Konfiguration dieser Daten (Obligo-Buchhaltung aus) bucht sie keinen Obligo- oder Reservierungseintrag — ein ehrliches, aus der Konfiguration folgendes ∅, keine Lücke.</li><li><b><b>Wareneingang</b></b> (<code>M_InOut</code>, eingehend) — die Ware kommt an, der Bestand steigt.</li><li><b><b>Rechnung (Lieferant)</b></b> — bucht Soll <b>Verrechnung Wareneingang</b> / Haben <b>Verbindlichkeiten</b>.</li><li><b>Zuordnung</b> (<code>M_MatchInv</code>) — gleicht das Paar Verrechnung Wareneingang / nicht fakturierte Eingänge aus, das Eingang und Rechnung jeweils eröffnet haben, einschließlich einer Preisabweichung der Rechnung, aufgeteilt gegen den Bestand zum Zeitpunkt der Zuordnung. Die eigene Buchung von <code>M_MatchPO</code> bleibt mit der Durchschnittskostenrechnung dieser Daten ein ehrliches ∅ (der Zweig für Abweichungsbuchungen greift nur bei Standardkosten) — eine Tatsache der Konfiguration, im Witness durch Umschalten bewiesen, nicht angenommen.</li></ul>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERPUserGuide/#6-purchase-order-receipt-vendor-invoice-match" target="_blank">6 · Bestellung → Wareneingang → Lieferantenrechnung → Zuordnung …</a></p>', 188),
  ('de_DE', 4, '<p><strong>Part D — Your first purchase order (demo company)</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERP_FirstSetup/#part-d-your-first-purchase-order-demo-company" target="_blank">Part D — Your first purchase order (demo company) …</a></p>', 188),
  ('de_DE', 5, '<p>Same steps as Part C, in <b><b>Purchase Order</b></b> (window 181): vendor e.g. <i>Tree Farm Inc.</i>, document type <b>Purchase Order</b>, line tab <b>PO Line</b> (e.g. <i>Elm Tree</i> × 5 at 40.00), then <b>Complete</b>. Like a Standard Order, a standard Purchase Order creates no receipt or vendor invoice on Complete (verified: 0 new documents); the receipt is entered separately.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERP_FirstSetup/#part-d-your-first-purchase-order-demo-company" target="_blank">Part D — Your first purchase order (demo company) …</a></p>', 0))
INSERT INTO AD_CtxHelpMsg (AD_CtxHelpMsg_ID, AD_CtxHelpMsg_UU, AD_CtxHelp_ID, AD_Client_ID, AD_Org_ID, Created, CreatedBy, Updated, UpdatedBy, IsActive, MsgText)
SELECT COALESCE((SELECT AD_CtxHelpMsg_ID FROM AD_CtxHelpMsg WHERE AD_CtxHelpMsg_UU='ec5dc447-1992-5aef-8bec-f1b676a82be0'), nextidfunc((SELECT AD_Sequence_ID FROM AD_Sequence WHERE Name='AD_CtxHelpMsg' AND IsTableID='Y')::integer, 'N')), 'ec5dc447-1992-5aef-8bec-f1b676a82be0', toRecordId('AD_CtxHelp', '58265c07-f5bc-52c2-9cc6-3527dace43ca'), 0, 0, now(), 100, now(), 100, 'Y', (SELECT x.dict || COALESCE(string_agg(b.html, '' ORDER BY b.k) FILTER (WHERE b.k <= x.j), '') || COALESCE(max(b.more) FILTER (WHERE b.k = x.j + 1), '') FROM (SELECT y.dict, y.l, COALESCE((SELECT min(c.k) FROM (SELECT k, sum(length(html)) OVER (ORDER BY k) AS cum, nextlen FROM blk WHERE lang = y.l) c WHERE length(y.dict) + c.cum + c.nextlen > y.lim) - 1, (SELECT max(k) FROM blk WHERE lang = y.l)) AS j FROM (SELECT '<p><strong>' || r.Name || '</strong></p>' || COALESCE('<p><em>' || NULLIF(r.Description, '') || '</em></p>', '') || COALESCE('<p>' || NULLIF(r.Help, '') || '</p>', '') || '<hr>' AS dict, 'en' AS l, (SELECT c.FieldLength FROM AD_Column c JOIN AD_Table tb ON tb.AD_Table_ID=c.AD_Table_ID WHERE tb.TableName='AD_CtxHelpMsg' AND c.ColumnName='MsgText') AS lim) y) x JOIN blk b ON b.lang = x.l GROUP BY x.dict, x.j)
FROM AD_Tab r WHERE r.AD_Tab_ID=294
ON CONFLICT (AD_CtxHelpMsg_UU) DO UPDATE SET MsgText=EXCLUDED.MsgText, Updated=now() WHERE AD_CtxHelpMsg.MsgText IS DISTINCT FROM EXCLUDED.MsgText;
