INSERT INTO AD_CtxHelpMsg_Trl (AD_CtxHelpMsg_ID, AD_Language, AD_CtxHelpMsg_Trl_UU, AD_Client_ID, AD_Org_ID, Created, CreatedBy, Updated, UpdatedBy, IsActive, IsTranslated, MsgText)
SELECT toRecordId('AD_CtxHelpMsg', '61117643-f154-576d-9592-2d811e160ae2'), r.AD_Language, generate_uuid(), 0, 0, now(), 100, now(), 100, 'Y', 'N', (SELECT x.dict || COALESCE(string_agg(b.html, '' ORDER BY b.k) FILTER (WHERE b.k <= x.j), '') || COALESCE(max(b.more) FILTER (WHERE b.k = x.j + 1), '') FROM (SELECT y.dict, y.l, COALESCE((SELECT min(c.k) FROM (SELECT k, sum(length(html)) OVER (ORDER BY k) AS cum, nextlen FROM blk WHERE lang = y.l) c WHERE length(y.dict) + c.cum + c.nextlen > y.lim) - 1, (SELECT max(k) FROM blk WHERE lang = y.l)) AS j FROM (SELECT '<p><strong>' || r.Name || '</strong></p>' || COALESCE('<p><em>' || NULLIF(r.Description, '') || '</em></p>', '') || COALESCE('<p>' || NULLIF(r.Help, '') || '</p>', '') || '<hr>' AS dict, CASE WHEN EXISTS (SELECT 1 FROM blk WHERE lang = r.AD_Language) THEN r.AD_Language ELSE 'en' END AS l, (SELECT c.FieldLength FROM AD_Column c JOIN AD_Table tb ON tb.AD_Table_ID=c.AD_Table_ID WHERE tb.TableName='AD_CtxHelpMsg_Trl' AND c.ColumnName='MsgText') AS lim) y) x JOIN blk b ON b.lang = x.l GROUP BY x.dict, x.j)
FROM AD_Process_Trl r WHERE r.AD_Process_ID=310
ON CONFLICT (AD_CtxHelpMsg_ID, AD_Language) DO UPDATE SET MsgText=EXCLUDED.MsgText, Updated=now() WHERE AD_CtxHelpMsg_Trl.MsgText IS DISTINCT FROM EXCLUDED.MsgText;
UPDATE AD_Process SET AD_CtxHelp_ID=toRecordId('AD_CtxHelp', 'c5a8669f-379e-531a-bd14-82a28f75cb9a'), Updated=now() WHERE AD_Process_ID=310 AND AD_CtxHelp_ID IS NULL;

-- process 53161 Initial Tenant Setup: FS3 (twin help 1000010)
INSERT INTO AD_CtxHelp (AD_CtxHelp_ID, AD_CtxHelp_UU, AD_Client_ID, AD_Org_ID, Created, CreatedBy, Updated, UpdatedBy, IsActive, CtxType, Name, Description)
SELECT COALESCE((SELECT AD_CtxHelp_ID FROM AD_CtxHelp WHERE AD_CtxHelp_UU='84ebdec5-3004-5104-8e20-cc3ca101b187'), nextidfunc((SELECT AD_Sequence_ID FROM AD_Sequence WHERE Name='AD_CtxHelp' AND IsTableID='Y')::integer, 'N')), '84ebdec5-3004-5104-8e20-cc3ca101b187', 0, 0, now(), 100, now(), 100, 'Y', 'P', 'Step 3 · Run Initial Tenant Setup', 'https://red1oon.github.io/BIMCompiler/ERP_FirstSetup/#step-3-run-initial-tenant-setup'
ON CONFLICT (AD_CtxHelp_UU) DO UPDATE SET Name=EXCLUDED.Name, Description=EXCLUDED.Description, Updated=now() WHERE (AD_CtxHelp.Name, AD_CtxHelp.Description) IS DISTINCT FROM (EXCLUDED.Name, EXCLUDED.Description);
WITH blk(lang, k, html, more, nextlen) AS (VALUES
  ('en', 1, '<p><strong>Step 3 · Run Initial Tenant Setup</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERP_FirstSetup/#step-3-run-initial-tenant-setup" target="_blank">Step 3 · Run Initial Tenant Setup …</a></p>', 158),
  ('en', 2, '<ol><li value="1">In the menu on the left, open the folders and click <b>Initial Tenant Setup</b>. (This is iDempiere''s <i>Initial Client Setup</i>, process 53161.)</li><li value="2">Fill in the fields:<ul><li><b>Tenant (Client) name</b>, for example <code>FirstCo</code>;</li><li><b><b>Currency</b></b>: any active currency in the list (163 of them; <b>USD</b> is preselected);</li><li><b><b>Country</b></b>: the country of your company''s address (249 countries; <b>United States</b> is preselected, as iDempiere''s setup does for an English login);</li><li><b>Administrator user</b>, for example <code>owner</code>;</li><li><b>Chart of accounts</b>: <i>iDempiere default (311 accounts)</i>, or <i>Load your own file</i> (see below).</li></ul></li><li value="3">Click <b>Create tenant</b>.</li></ol>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERP_FirstSetup/#step-3-run-initial-tenant-setup" target="_blank">Step 3 · Run Initial Tenant Setup …</a></p>', 158),
  ('en', 3, '<p>The new company is created and installed in your browser. In the measured run it became <b>client 17</b>, with <b>530 rows</b> written and saved. The setup wrote the company, its HQ organization (with an address in the country you chose), an administrator and a user role, a calendar for the current year with <b>12 monthly periods</b>, the full <b>311-account</b> iDempiere default chart of accounts, an accounting schema with its default and GL accounts, iDempiere''s <b>42 standard document types</b> with their <b>12 GL categories</b> and number sequences, one warehouse with a locator and an address, a price list (<i>Standard</i>, valid from today) in which the sample product costs <b>1.00</b>, a business partner group, one sample business partner <i>Standard BP</i> with an address, a tax category (<i>Sales Tax</i> for the United States, <i>Standard</i> otherwise) with one tax rate, one sample product in that category, the <b>Immediate</b> payment term and one sample sales invoice. Everything is in the currency you chose.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERP_FirstSetup/#step-3-run-initial-tenant-setup" target="_blank">Step 3 · Run Initial Tenant Setup …</a></p>', 158),
  ('en', 4, '<ol><li value="4">Click <b>Enter FirstCo</b>. The sign-in card now lists your administrator (<code>owner</code>). Pick it and log in. The new administrator''s menu holds <b>534</b> entries.</li></ol>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERP_FirstSetup/#step-3-run-initial-tenant-setup" target="_blank">Step 3 · Run Initial Tenant Setup …</a></p>', 158),
  ('en', 5, '<p><b>Loading your own chart of accounts</b></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERP_FirstSetup/#step-3-run-initial-tenant-setup" target="_blank">Step 3 · Run Initial Tenant Setup …</a></p>', 158),
  ('en', 6, '<p>Choose <b>Chart of accounts → Load your own file</b> and pick a CSV file in iDempiere''s own format (the layout of iDempiere''s <code>data/import/AccountingUS.csv</code>: Value, Name, Description, Type, Sign, Document, Summary, <b>Default_Account</b>, …). As in iDempiere:</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERP_FirstSetup/#step-3-run-initial-tenant-setup" target="_blank">Step 3 · Run Initial Tenant Setup …</a></p>', 158),
  ('en', 7, '<ul><li>only lines with a <b>Default_Account</b> key are read; the same account value on several lines is one account serving several keys;</li><li>the file must define <b>every</b> default account the accounting schema needs (53 keys in this dictionary, for example <code>C_RECEIVABLE_ACCT</code>). If one is missing, nothing is created and the form says which, e.g. <i>"Account not defined: C_RECEIVABLE_ACCT"</i>.</li></ul>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERP_FirstSetup/#step-3-run-initial-tenant-setup" target="_blank">Step 3 · Run Initial Tenant Setup …</a></p>', 158),
  ('en', 8, '<p><b>Sales Order → New</b> in your own company offers its 7 sales document types (Standard Order, POS Order, Prepay Order and the others).</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERP_FirstSetup/#step-3-run-initial-tenant-setup" target="_blank">Step 3 · Run Initial Tenant Setup …</a></p>', 0))
INSERT INTO AD_CtxHelpMsg (AD_CtxHelpMsg_ID, AD_CtxHelpMsg_UU, AD_CtxHelp_ID, AD_Client_ID, AD_Org_ID, Created, CreatedBy, Updated, UpdatedBy, IsActive, MsgText)
SELECT COALESCE((SELECT AD_CtxHelpMsg_ID FROM AD_CtxHelpMsg WHERE AD_CtxHelpMsg_UU='7d7a82d4-c97c-5ac2-86f1-9c57c6af2ea4'), nextidfunc((SELECT AD_Sequence_ID FROM AD_Sequence WHERE Name='AD_CtxHelpMsg' AND IsTableID='Y')::integer, 'N')), '7d7a82d4-c97c-5ac2-86f1-9c57c6af2ea4', toRecordId('AD_CtxHelp', '84ebdec5-3004-5104-8e20-cc3ca101b187'), 0, 0, now(), 100, now(), 100, 'Y', (SELECT x.dict || COALESCE(string_agg(b.html, '' ORDER BY b.k) FILTER (WHERE b.k <= x.j), '') || COALESCE(max(b.more) FILTER (WHERE b.k = x.j + 1), '') FROM (SELECT y.dict, y.l, COALESCE((SELECT min(c.k) FROM (SELECT k, sum(length(html)) OVER (ORDER BY k) AS cum, nextlen FROM blk WHERE lang = y.l) c WHERE length(y.dict) + c.cum + c.nextlen > y.lim) - 1, (SELECT max(k) FROM blk WHERE lang = y.l)) AS j FROM (SELECT '<p><strong>' || r.Name || '</strong></p>' || COALESCE('<p><em>' || NULLIF(r.Description, '') || '</em></p>', '') || COALESCE('<p>' || NULLIF(r.Help, '') || '</p>', '') || '<hr>' AS dict, 'en' AS l, (SELECT c.FieldLength FROM AD_Column c JOIN AD_Table tb ON tb.AD_Table_ID=c.AD_Table_ID WHERE tb.TableName='AD_CtxHelpMsg' AND c.ColumnName='MsgText') AS lim) y) x JOIN blk b ON b.lang = x.l GROUP BY x.dict, x.j)
FROM AD_Process r WHERE r.AD_Process_ID=53161
ON CONFLICT (AD_CtxHelpMsg_UU) DO UPDATE SET MsgText=EXCLUDED.MsgText, Updated=now() WHERE AD_CtxHelpMsg.MsgText IS DISTINCT FROM EXCLUDED.MsgText;
