WITH blk(lang, k, html, more, nextlen) AS (VALUES
  ('en', 1, '<p><strong>Step 4 · Create a customer</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERP_FirstSetup/#step-4-create-a-customer" target="_blank">Step 4 · Create a customer …</a></p>', 144),
  ('en', 2, '<ol><li value="1">Open <b><b>Business Partner</b></b> (window 123) and click <b>New record</b> on the toolbar.</li><li value="2"><b><b>Organization</b></b>: pick your company''s HQ, or <code>*</code> to share the record across organizations.</li><li value="3"><b>Search Key</b>: e.g. <code>C-001</code>. <b>Name</b>: e.g. <code>Acme Retail Sdn Bhd</code>.</li><li value="4"><b><b>Business Partner Group</b></b>: pick <b>Standard</b>, the group the setup created for your company.</li><li value="5">Tick <b><b>Customer</b></b> and click <b>Save</b> on the toolbar.</li></ol>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERP_FirstSetup/#step-4-create-a-customer" target="_blank">Step 4 · Create a customer …</a></p>', 144),
  ('en', 3, '<p>Your company''s <b>HQ</b> is in the Organization list, and the records the setup created show in their own windows: Price List, Calendar and Warehouse 1 record each, Business Partner 3 (the sample plus the two you make).</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERP_FirstSetup/#step-4-create-a-customer" target="_blank">Step 4 · Create a customer …</a></p>', 140),
  ('en', 4, '<p><strong>Step 5 · Create a vendor</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERP_FirstSetup/#step-5-create-a-vendor" target="_blank">Step 5 · Create a vendor …</a></p>', 140),
  ('en', 5, '<p>Same window and steps as Step 4, with <b>Vendor</b> ticked instead of Customer, e.g. <code>V-001</code> <code>Kedai Bekalan Sdn Bhd</code>.</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERP_FirstSetup/#step-5-create-a-vendor" target="_blank">Step 5 · Create a vendor …</a></p>', 0))
