  ('en', 1, '<p><strong>Step 6b · A first sales order in your own company</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERP_FirstSetup/#step-6b-a-first-sales-order-in-your-own-company" target="_blank">Step 6b · A first sales order in your own company …</a></p>', 190),
  ('en', 2, '<p>iDempiere''s setup makes the price list <b>Standard</b> a <i>purchase</i> price list. Make it usable for sales once:</p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERP_FirstSetup/#step-6b-a-first-sales-order-in-your-own-company" target="_blank">Step 6b · A first sales order in your own company …</a></p>', 190),
  ('en', 3, '<ol><li value="1">Open <b><b>Price List</b></b> (window 146), select <b>Standard</b>, tick <b>Sales Price list</b> and <b>Save</b>.</li><li value="2">Open <b><b>Sales Order</b></b> (window 143), <b>New record</b>. The <b>Price List</b> is already <i>Standard</i> (your company''s default). <b><b>Business Partner</b></b>: <i>Standard BP</i>; <b>Target Document Type</b>: <i>Standard Order</i>. <b>Save</b>.</li><li value="3">On <b>Order Line</b>, <b>New record</b>, <b><b>Product</b></b>: <i>Standard Product</i>, <b>Quantity</b> <code>2</code>. The price (<b>1.00</b>), the UOM (<i>Each</i>) and the tax fill in. <b>Save</b>, then go back to the order and <b>Complete</b>.</li></ol>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERP_FirstSetup/#step-6b-a-first-sales-order-in-your-own-company" target="_blank">Step 6b · A first sales order in your own company …</a></p>', 0))
