  ('en', 1, '<p><strong>Step 8 · Add a line</strong></p>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERP_FirstSetup/#step-8-add-a-line" target="_blank">Step 8 · Add a line …</a></p>', 130),
  ('en', 2, '<ol><li value="1">Open the <b>Order Line</b> tab and click <b>New record</b>. You do not have to click <b>Save</b> on the header first: as in iDempiere, moving to another tab saves the record you were typing. If a required field is still empty, the header is not saved and you stay on it, with the field marked. The <b>Order Line</b> tab only ever lists the lines of the order you are on, including lines added during this session to other orders.</li><li value="2"><b><b>Product</b></b>: e.g. <i>Oak Tree</i>. Choosing it fills the <b>Price</b> from the order''s price list (<code>61.75</code>), the <b><b>UOM</b></b> (<i>Each</i>) and the <b><b>Tax</b></b> (<i>Standard</i>), as iDempiere does. <b>Quantity</b>: <code>2</code>. Line Net Amount becomes <b>123.50</b>.</li><li value="4">Click <b>Save</b>.</li></ol>', '<p><a href="https://red1oon.github.io/BIMCompiler/ERP_FirstSetup/#step-8-add-a-line" target="_blank">Step 8 · Add a line …</a></p>', 0))
INSERT INTO AD_CtxHelpMsg_Trl (AD_CtxHelpMsg_ID, AD_Language, AD_CtxHelpMsg_Trl_UU, AD_Client_ID, AD_Org_ID, Created, CreatedBy, Updated, UpdatedBy, IsActive, IsTranslated, MsgText)
SELECT toRecordId('AD_CtxHelpMsg', 'd036dc1d-52ad-52e5-8587-e2992e600196'), r.AD_Language, generate_uuid(), 0, 0, now(), 100, now(), 100, 'Y', 'N', (SELECT x.dict || COALESCE(string_agg(b.html, '' ORDER BY b.k) FILTER (WHERE b.k <= x.j), '') || COALESCE(max(b.more) FILTER (WHERE b.k = x.j + 1), '') FROM (SELECT y.dict, y.l, COALESCE((SELECT min(c.k) FROM (SELECT k, sum(length(html)) OVER (ORDER BY k) AS cum, nextlen FROM blk WHERE lang = y.l) c WHERE length(y.dict) + c.cum + c.nextlen > y.lim) - 1, (SELECT max(k) FROM blk WHERE lang = y.l)) AS j FROM (SELECT '<p><strong>' || r.Name || '</strong></p>' || COALESCE('<p><em>' || NULLIF(r.Description, '') || '</em></p>', '') || COALESCE('<p>' || NULLIF(r.Help, '') || '</p>', '') || '<hr>' AS dict, CASE WHEN EXISTS (SELECT 1 FROM blk WHERE lang = r.AD_Language) THEN r.AD_Language ELSE 'en' END AS l, (SELECT c.FieldLength FROM AD_Column c JOIN AD_Table tb ON tb.AD_Table_ID=c.AD_Table_ID WHERE tb.TableName='AD_CtxHelpMsg_Trl' AND c.ColumnName='MsgText') AS lim) y) x JOIN blk b ON b.lang = x.l GROUP BY x.dict, x.j)
